input.sparql:
SELECT ?zone ?point ?pc ?tsid WHERE {
  ?zone rdfs:label ?zl .
  FILTER (CONTAINS(?zl, "Perimeter") && (!CONTAINS(?zl, "Room")))
  ?zone brick:hasPoint ?point .
  ?point a brick:AirTemperatureSensor .
  OPTIONAL { ?point ref:hasExternalReference ?e ; ref:hasTimeseriesId ?tsid . }
}

SELECT DISTINCT ?p WHERE {
  ?zone rdfs:label ?zl .
  FILTER (CONTAINS(?zl, "Perimeter") && (!CONTAINS(?zl, "Room")))
  ?zone brick:hasPoint ?p .
} LIMIT 50

SELECT ?p ?x WHERE {
  ?p ref:hasExternalReference ?x .
  FILTER (CONTAINS(str(?x), "tsref") || true)
  FILTER (CONTAINS(str(?x), "Zone_F1_Z04") || CONTAINS(str(?x), "Zone_F2_Z03"))
}
